from pathlib import Path
import subprocess,tempfile
root=Path(__file__).resolve().parents[1]
boundary='#ifndef HOST_BOUNDARY\n#define HOST_BOUNDARY\n#include <stdint.h>\n#include <math.h>\n#include "config.h"\n#include "qcar_types.h"\ntypedef uint8_t uint8;typedef uint16_t uint16;typedef uint32_t uint32;typedef int32_t int32;typedef int16_t int16;\n#define IMU_ATTITUDE_CALIBRATING 0\nextern struct host_attitude {struct {float x,y,z;} gyro;} attitude_state;\nextern volatile float imu_roll_deg,imu_pitch_deg,imu_sample_dt_ms,imu_asc_roll_deg,imu_asc_pitch_deg,imu_asc_yaw_deg;\nextern volatile uint32 imu_sample_sequence;\nextern volatile int32 imu_attitude_status;\nuint32 interrupt_global_disable(void);void interrupt_global_enable(uint32);void small_driver_set_duty(int16,int16);void motor_m_ctrl(int);\n#endif\n'
test='#include "balance_control.h"\n#include "wheel_hold.h"\n#include "asc_control.h"\n#include <assert.h>\n#include <stdio.h>\nstruct host_attitude attitude_state;\nvolatile float imu_roll_deg,imu_pitch_deg,imu_sample_dt_ms=1,imu_asc_roll_deg,imu_asc_pitch_deg,imu_asc_yaw_deg;\nvolatile uint32 imu_sample_sequence;\nvolatile int32 imu_attitude_status;\nvolatile uint8 small_driver_feedback_fresh=1;\nvolatile uint32 small_driver_feedback_age_ms,small_driver_speed_frames;\nstatic wheel_encoder_sample_t encoder;\nstatic int left,right,ground;\nuint32 interrupt_global_disable(void){return 0;}void interrupt_global_enable(uint32 n){(void)n;}\nvoid small_driver_set_duty(int16 l,int16 r){left=l;right=r;}void motor_m_ctrl(int v){ground=v;}\nvoid wheel_encoder_snapshot(wheel_encoder_sample_t *p){*p=encoder;}\nuint8_t wheel_encoder_rebase_position(void){return 1;}\nstatic void near(float a,float b){assert(fabsf(a-b)<.02f);}\nstatic void tick(int fresh){if(fresh)++imu_sample_sequence;imu_pitch_deg=imu_asc_roll_deg;imu_roll_deg=-imu_asc_pitch_deg;balance_control_tick_1ms();}\nstatic void arm(void){\n balance_control_defaults();shacheflag=1;imu_attitude_status=1;small_driver_feedback_fresh=1;small_driver_feedback_age_ms=0;\n attitude_state.gyro.x=attitude_state.gyro.y=attitude_state.gyro.z=0;\n float rz,pz;asc_reference_zero(mono_params.balance_angle_x,mono_params.balance_angle_y,&rz,&pz);imu_asc_roll_deg=rz;imu_asc_pitch_deg=pz;imu_asc_yaw_deg=0;\n encoder=(wheel_encoder_sample_t){0};encoder.valid=encoder.position_valid=1;encoder.sequence=1;encoder.dt_ms=20;\n flywheel_speed_feedback_left=flywheel_speed_feedback_right=0;mode10_balance_arm();asc_yaw_enabled=0;ground_deadzone_enable=0;\n}\nint main(void){\n arm();tick(1);assert(balance_control_mode==10&&roll_rate_test_state==2&&!wheel_hold_enabled);assert(!left&&!right&&!ground);\n imu_asc_roll_deg+=1;tick(1);assert(left==432&&right==-432);tick(1);assert(left==720&&right==-720); /* positional, 1ms */\n imu_asc_roll_deg-=1;tick(1);tick(1);assert(!left&&!right); /* no retained incremental bias */\n flywheel_speed_feedback_left=1000;for(int i=0;i<18;i++)tick(1);float rz,pz;asc_reference_zero(mono_params.balance_angle_x,mono_params.balance_angle_y,&rz,&pz);near(dual_target[0],rz-1.5f);\n arm();tick(1);ground_angle_kp=ground_rate_test_kp=ground_rate_test_kd=asc_ground_rate_ki=0;\n asc_ground_speed_kp=asc_ground_speed_ki=asc_ground_speed_kd=0;ground_deadzone_enable=1;\n attitude_state.gyro.x=20;imu_asc_pitch_deg+=1;tick(1);assert(!ground);\n arm();asc_yaw_enabled=1;tick(1);imu_asc_yaw_deg=1;attitude_state.gyro.z=2;tick(1);assert(left==right&&left==-1120);\n arm();tick(1);small_driver_feedback_fresh=0;tick(1);assert(roll_rate_test_state==-4&&control_fault_reason==12&&!left&&!right&&!ground);\n arm();tick(1);encoder.age_ms=WHEEL_SPEED_ENCODER_TIMEOUT_MS;tick(1);assert(control_fault_reason==8&&!ground&&!left);\n arm();tick(1);imu_asc_roll_deg+=ASC_ROLL_PROTECT_DEG+1;tick(1);assert(roll_rate_test_state==-2&&control_fault_reason==5&&!left&&!ground);\n arm();tick(1);for(unsigned i=0;i<BALANCE_IMU_STALE_MS;i++)tick(0);assert(roll_rate_test_state==-1&&control_fault_reason==4&&!left&&!ground);\n arm();fly_rate_kd=NAN;tick(1);assert(roll_rate_test_state==-3&&!left&&!ground);\n arm();asc_yaw_enabled=.5f;tick(1);assert(roll_rate_test_state==-3&&!left&&!ground);\n arm();tick(1);roll_rate_test_stop();tick(1);assert(balance_control_mode==0&&!left&&!right&&!ground);\n puts("PASS: real Mode10 1ms dispatch, ASC signs/mixing, reference recovery, yaw, ground disable, sensor/driver/encoder/tilt faults and Stop");\n}\n'
with tempfile.TemporaryDirectory(prefix='qcar-asc-integration-') as d:
 w=Path(d);(w/'zf_common_headfile.h').write_text(boundary,encoding='utf-8');(w/'test.c').write_text(test,encoding='utf-8');exe=w/'test.exe'
 sources=[root/'code'/n for n in ['balance_control.c','wheel_hold.c','pid.c','asc_control.c','asc_pid.c']]
 subprocess.run(['gcc','-std=c99','-Wall','-Wextra','-Werror','-I'+str(w),'-I'+str(root/'code'),*[str(p) for p in sources],str(w/'test.c'),'-lm','-o',str(exe)],check=True)
 subprocess.run([str(exe)],check=True,timeout=10)
